/**
 * The shape of a quest's map outline: the roughest contours of what its map
 * will look like, as SVG path data generated by `scripts/build-outline.mjs`.
 *
 * Each shape is keyed by the place it draws, which is the join a later fill
 * needs and nothing more: an outline is not interactive.
 */

/** One place's contour. */
export interface IOutlineShape<Id extends string = string> {
  readonly id: Id;
  /** SVG path data, in the outline's `viewBox` units. */
  readonly d: string;
}

export interface IOutline<Id extends string = string> {
  /** What the outline shows, for the SVG's accessible name. */
  readonly label: string;
  readonly viewBox: string;
  /** One per place the source can draw; a place too small for it has none. */
  readonly shapes: ReadonlyArray<IOutlineShape<Id>>;
  /**
   * Land drawn for context that is none of the places — Antarctica and
   * Taiwan on the countries map — as one path, so the coastline is whole
   * without the count changing. Never filled by progress.
   */
  readonly unkeyed?: string;
}
